def min_window(s1, s2):
    n, m = len(s1), len(s2)
    best_len = float('inf')
    best_start = -1

    i = 0
    while i < n:
        j = 0
        start = i
        while i < n:
            if s1[i] == s2[j]:
                j += 1
                if j == m:
                    break
            i += 1
        if j < m:
            break

        end = i
        j = m - 1
        while j >= 0:
            if s1[i] == s2[j]:
                j -= 1
            i -= 1
        i += 1

        if end - i + 1 < best_len:
            best_len = end - i + 1
            best_start = i

        i += 1

    return "" if best_start == -1 else s1[best_start:best_start + best_len]

